(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(2500);
  const out = { viewport: { w: innerWidth, h: innerHeight, dpr: devicePixelRatio } };
  out.chain = [];
  let el = document.querySelector('.pj-main');
  while (el && el.tagName !== 'HTML') {
    const cs = getComputedStyle(el);
    out.chain.push({
      tag: el.tagName + (el.className ? '.' + String(el.className).split(' ')[0] : ''),
      w: Math.round(el.getBoundingClientRect().width),
      maxW: cs.maxWidth, width: cs.width, zoom: cs.zoom, transform: cs.transform, position: cs.position, display: cs.display,
    });
    el = el.parentElement;
  }
  out.bodyStyle = { zoom: getComputedStyle(document.body).zoom, transform: getComputedStyle(document.body).transform };
  out.htmlStyle = { zoom: getComputedStyle(document.documentElement).zoom };
  out.dpr = devicePixelRatio;
  out.screen = { w: screen.width, h: screen.height, availW: screen.availWidth };
  return JSON.stringify(out);
})()
